<?php
require_once __DIR__.'/../config/auth.php';require_role('kasir');header('Content-Type: application/json');if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;}verify_csrf();$data=json_decode(file_get_contents('php://input'),true);$id=(int)($data['id']??0);$action=$data['action']??'';$pdo=db();
try{$pdo->beginTransaction();$s=$pdo->prepare("SELECT * FROM transactions WHERE id=? AND branch_id=? AND status='open' FOR UPDATE");$s->execute([$id,branch_id()]);$t=$s->fetch();if(!$t)throw new RuntimeException('Pesanan sudah diproses atau tidak ditemukan.');$method=null;$change=0;
 if($action==='pay'){$shift=current_shift();if(!$shift)throw new RuntimeException('Buka shift kasir terlebih dahulu.');$method=$data['method']??'';$amount=(float)($data['amount']??0);if(!in_array($method,['tunai','qris'],true))throw new RuntimeException('Metode pembayaran tidak valid.');if($method==='qris')$amount=(float)$t['total'];if($amount<(float)$t['total'])throw new RuntimeException('Jumlah pembayaran kurang.');$change=$amount-(float)$t['total'];$pdo->prepare('INSERT INTO payments(transaction_id,method,amount,change_amount) VALUES(?,?,?,?)')->execute([$id,$method,$amount,$change]);$pdo->prepare("UPDATE transactions SET status='paid',shift_id=? WHERE id=?")->execute([$shift['id'],$id]);}
 elseif($action==='cancel'){$d=$pdo->prepare('SELECT id,product_id,quantity FROM transaction_details WHERE transaction_id=?');$d->execute([$id]);$restore=$pdo->prepare('UPDATE products SET stock=stock+? WHERE id=? AND branch_id=?');$restoreTop=$pdo->prepare('UPDATE toppings SET stock=stock+? WHERE id=? AND branch_id=?');$topIds=$pdo->prepare('SELECT topping_id FROM transaction_detail_toppings WHERE transaction_detail_id=? AND topping_id IS NOT NULL');foreach($d as $item){$restore->execute([$item['quantity'],$item['product_id'],branch_id()]);$topIds->execute([$item['id']]);foreach($topIds->fetchAll(PDO::FETCH_COLUMN) as $topId)$restoreTop->execute([$item['quantity'],$topId,branch_id()]);}$pdo->prepare("DELETE FROM stock_movements WHERE reference_id=? AND type='sale'")->execute([$id]);$pdo->prepare("UPDATE transactions SET status='cancelled' WHERE id=?")->execute([$id]);}
 else throw new RuntimeException('Tindakan tidak valid.');$pdo->commit();audit_log($action==='pay'?'order_paid':'order_cancelled','transaction',$id,['status'=>'open'],['status'=>$action==='pay'?'paid':'cancelled','invoice'=>$t['invoice']]);echo json_encode(['ok'=>true,'invoice'=>$t['invoice'],'total'=>(float)$t['total'],'change'=>$change,'method'=>$method,'order_name'=>$t['order_name'],'table_number'=>$t['table_number']]);
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();http_response_code(422);echo json_encode(['message'=>$e instanceof RuntimeException?$e->getMessage():'Pesanan gagal diproses.']);}
